import { describe, expect, it } from "vitest";

import { classConflictsWithSchedule } from "../src/conflict";
import { CATALOG_SECTIONS, STUDENT_SCHEDULE } from "../src/fixtures";
import { getFilteredCatalogPage } from "../src/scheduleFilter";

// Ground truth, computed independently of the function under test by
// filtering the raw fixture directly.
const NON_CONFLICTING_IDS = CATALOG_SECTIONS.filter(
  (s) => !classConflictsWithSchedule(s.meetings, STUDENT_SCHEDULE)
).map((s) => s.id);

const CONFLICTING_ID_SET = new Set(
  CATALOG_SECTIONS.filter((s) =>
    classConflictsWithSchedule(s.meetings, STUDENT_SCHEDULE)
  ).map((s) => s.id)
);

describe("getFilteredCatalogPage", () => {
  it("never returns a section that conflicts with the student's schedule", () => {
    const pageSize = 10;
    const rawTotalPages = Math.ceil(CATALOG_SECTIONS.length / pageSize);

    for (let page = 1; page <= rawTotalPages; page++) {
      const result = getFilteredCatalogPage(page, pageSize, STUDENT_SCHEDULE);
      for (const item of result.items) {
        expect(CONFLICTING_ID_SET.has(item.id)).toBe(false);
      }
    }
  });

  it.each([10, 6, 27])(
    "reports totalCount as the number of non-conflicting sections, not the raw catalog (pageSize=%d)",
    (pageSize) => {
      const result = getFilteredCatalogPage(1, pageSize, STUDENT_SCHEDULE);
      expect(result.totalCount).toBe(NON_CONFLICTING_IDS.length);
    }
  );

  it.each([10, 6, 27])(
    "reports totalPages consistent with totalCount and pageSize (pageSize=%d)",
    (pageSize) => {
      const result = getFilteredCatalogPage(1, pageSize, STUDENT_SCHEDULE);
      const expectedTotalPages = Math.ceil(NON_CONFLICTING_IDS.length / pageSize);
      expect(result.totalPages).toBe(expectedTotalPages);
    }
  );

  it.each([10, 6, 27])(
    "every page except the true last page has exactly pageSize non-conflicting items (pageSize=%d)",
    (pageSize) => {
      const expectedTotalPages = Math.ceil(NON_CONFLICTING_IDS.length / pageSize);

      for (let page = 1; page <= expectedTotalPages; page++) {
        const result = getFilteredCatalogPage(page, pageSize, STUDENT_SCHEDULE);
        const isLastPage = page === expectedTotalPages;
        const expectedCount = isLastPage
          ? NON_CONFLICTING_IDS.length - pageSize * (expectedTotalPages - 1)
          : pageSize;

        expect(result.items).toHaveLength(expectedCount);
      }
    }
  );

  it.each([10, 6, 27])(
    "returns the full non-conflicting set exactly once each, with no gaps or duplicates (pageSize=%d)",
    (pageSize) => {
      const expectedTotalPages = Math.ceil(NON_CONFLICTING_IDS.length / pageSize);
      const seenIds: string[] = [];

      for (let page = 1; page <= expectedTotalPages; page++) {
        const result = getFilteredCatalogPage(page, pageSize, STUDENT_SCHEDULE);
        seenIds.push(...result.items.map((s) => s.id));
      }

      expect(new Set(seenIds).size).toBe(seenIds.length);
      expect([...seenIds].sort()).toEqual([...NON_CONFLICTING_IDS].sort());
    }
  );

  it("returns an empty page when requesting a page number past the true last page", () => {
    const pageSize = 10;
    const expectedTotalPages = Math.ceil(NON_CONFLICTING_IDS.length / pageSize);

    const result = getFilteredCatalogPage(
      expectedTotalPages + 1,
      pageSize,
      STUDENT_SCHEDULE
    );

    expect(result.items).toHaveLength(0);
  });
});
